/// The shape of buttons, token `shape.button`.
enum FlButtonShape {
  /// Square corners.
  square,

  /// Corners with the `radiusControl` radius.
  rounded,

  /// Semicircular ends.
  pill,
}

/// The radii of `shape.radius` and the shape of buttons.
final class FlShapeTokens {
  /// One value per field; [FlTokens.defaults] holds the project's.
  const FlShapeTokens({
    required this.radiusControl,
    required this.radiusCard,
    required this.radiusSheet,
    required this.radiusButton,
    required this.radiusButtonLarge,
    required this.radiusXs,
    required this.radiusSm,
    required this.radiusMd,
    required this.radiusLg,
    required this.radiusXl,
    required this.radiusXxl,
    required this.button,
  });

  /// Radius in logical pixels, token `shape.radius.control`.
  final double radiusControl;

  /// Radius in logical pixels, token `shape.radius.card`.
  final double radiusCard;

  /// Radius in logical pixels, token `shape.radius.sheet`.
  final double radiusSheet;

  /// Radius in logical pixels, token `shape.radius.button`.
  final double radiusButton;

  /// Radius in logical pixels, token `shape.radius.buttonLarge`.
  final double radiusButtonLarge;

  /// Radius in logical pixels, token `shape.radius.xs`.
  final double radiusXs;

  /// Radius in logical pixels, token `shape.radius.sm`.
  final double radiusSm;

  /// Radius in logical pixels, token `shape.radius.md`.
  final double radiusMd;

  /// Radius in logical pixels, token `shape.radius.lg`.
  final double radiusLg;

  /// Radius in logical pixels, token `shape.radius.xl`.
  final double radiusXl;

  /// Radius in logical pixels, token `shape.radius.xxl`.
  final double radiusXxl;

  /// The shape of buttons, token `shape.button`.
  final FlButtonShape button;

  /// The border radius of buttons, derived from [button].
  BorderRadius get buttonRadius => switch (button) {
    FlButtonShape.square => BorderRadius.zero,
    FlButtonShape.rounded => BorderRadius.circular(radiusControl),
    FlButtonShape.pill => BorderRadius.circular(9999),
  };
}

